import sys,numpy as np
from scipy.spatial import cKDTree
sys.path.insert(0,'/opt/tools');from rcb_brush import Session
sys.path.insert(0,'/app/output');from gen import STROKES,smooth_centerline,OFFSETS,PRESS_DELTAS
