for x in a:s.step(x)
s.painter.finish(); rec=s.strokes();skT=np.load('/app/output/target_skel.npy');tp=np.argwhere(skT>0);treeT=cKDTree(tp)
def thin(img):
 img=img.copy().astype(np.uint8);changed=True
 while changed:
  changed=False
  for ph in (0,1):
   p=np.pad(img,1);n=[p[:-2,1:-1],p[:-2,2:],p[1:-1,2:],p[2:,2:],p[2:,1:-1],p[2:,:-2],p[1:-1,:-2],p[:-2,:-2]];nn=sum(n);tr=sum(((n[i]==0)&(n[(i+1)%8]==1)) for i in range(8));c=(img==1)&(nn>=2)&(nn<=6)&(tr==1)
   if ph==0:c&=(n[0]*n[2]*n[4]==0)&(n[2]*n[4]*n[6]==0)
   else:c&=(n[0]*n[2]*n[6]==0)&(n[0]*n[4]*n[6]==0)
   if c.any():img[c]=0;changed=True
 return img
for i,((wrapped,),r,(du,dv),dp) in enumerate(zip(STROKES,rec,OFFSETS,PRESS_DELTAS),1):
 m=np.zeros((1024,1024),bool);r0,c0=r['mask_bbox'];q=np.asarray(r['mask'])>=128;m[r0:r0+q.shape[0],c0:c0+q.shape[1]]=q; pp=np.argwhere(thin(m)); trp=cKDTree(pp)
 ctrl=[(u+du,v+dv,p+dp) for u,v,p in wrapped];curve=smooth_centerline(ctrl);uv=curve[:,:2];res=[]
 for j in np.linspace(5,len(uv)-6,9).astype(int):
  c=uv[j];td,ti=treeT.query([c[1],c[0]]);vd,vi=trp.query([c[1],c[0]]);tv,tu=tp[ti];pv,pu=pp[vi]
  vec=np.array([tu-pu,tv-pv]);res.append((round(j/(len(uv)-1),2),round(td,1),round(vd,1),tuple(vec)))
 print(i,res)
